import { CfMeetClient } from '@cfmeet/platform-sdk';
const cfmeet = new CfMeetClient({ baseUrl: 'https://api.cfmeet.com', auth: { type: 'platformCredential', credential: process.env.CFMEET_API_CREDENTIAL! } });
const context = await cfmeet.gateway.getDeveloperPlatformContext();

import 'package:cfmeet_platform_sdk/cfmeet_platform_sdk.dart';
final client = CfMeetClient(baseUrl: 'https://api.cfmeet.com', auth: CfMeetAuth.platformCredential(Platform.environment['CFMEET_API_CREDENTIAL']!));
final context = await client.domain('gateway').call('getDeveloperPlatformContext');
